function modeDirective(mode,userName='用户角色') {
  const addressing=`对话称呼沿用 ${userName} 的名字或双方已有的爱称，也可以自然说“你”，不称对方为第三人称。`;
  return (mode==='story'
    ? '【小手机当前模式：剧情内】你在故事世界中与用户角色本人私聊。依据提供的用户人设理解对方；不要提屏幕、幕后玩家、正在看故事或第四面墙。'
    : '【小手机当前模式：第四面墙】你知道小手机另一端是正在操控用户角色的真实幕后玩家，直接和屏幕前的本人私聊。用户角色的名字仍是对方在这段关系中的称呼，不因此改叫“玩家”。小手机是正文之外的窗口，不要求正文里出现手机；只在手机消息中越过第四面墙。')+addressing;
}
function readPersona(ctx) {
  const value=ctx.powerUserSettings?.persona_description;
  if(typeof value!=='string')return '';
  try{return String(ctx.substituteParams?.(value)??value);}catch{return value;}
}

const MEDIA_DEFAULTS = Object.freeze({ttsProvider:'minimax',minimaxKey:'',minimaxVoice:'',minimaxModel:'',minimaxEndpoint:'',elevenKey:'',elevenVoice:'',elevenModel:'',elevenEndpoint:'',ttsSpeed:1,imageProvider:'nai',naiKey:'',naiModel:'',naiEndpoint:'',naiWidth:832,naiHeight:1216,naiSteps:28,naiScale:5,naiNegative:'',openaiImageKey:'',openaiImageModel:'',openaiImageEndpoint:'',openaiImageSize:'1024x1024',openaiImageQuality:'auto',autoImages:false,stickers:[]});
function mediaSettingsKey(chat){return 'rf-imessage-media:'+encodeURIComponent(chat);}
function validImageURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
function importStickers(value){
 let data;if(typeof value!=='string')data=value;else {try{data=JSON.parse(value);}catch{data=value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).map(line=>{const m=line.match(/^(.+?)(?:\t|\s*\|\s*|\s+(?=https?:\/\/))(https?:\/\/\S+)$/);if(!m)throw Error('表情包每行请写：名字 | 图片链接，或导入 JSON 数组。');return {name:m[1],url:m[2]};});}}
 if(data&&typeof data==='object'&&!Array.isArray(data))data=Object.entries(data).map(([name,url])=>({name,url}));
 if(!Array.isArray(data)||data.length>500)throw Error('表情包需要数组或名字与链接的映射，一次最多 500 个。');
 const names=new Set();return data.map(row=>{const name=String(row?.name??'').trim(),url=validImageURL(row?.url??row?.image??'');if(!name||name.length>80||/[<>\n\r]/.test(name)||!url)throw Error('表情包名称不能为空或含标签，图片需要 HTTP(S) 链接。');if(names.has(name))throw Error('表情包有重复名字：'+name);names.add(name);return {name,url};});
}
function richParts(text){
 const original=String(text??''),hasControl=/‹toy:[^›\r\n]*›|<toy:[^>\r\n]*>/i.test(original);text=original.replace(/‹toy:[^›\r\n]*›|<toy:[^>\r\n]*>/gi,'');const out=[],token=/<(voice|pic|sticker|clip|toy)\b[^>]*>([\s\S]*?)<\/\1\s*>|<call\s*(?:\/\s*)?>(?:([\s\S]*?)<\/call\s*>)?/gi;let last=0;
 function plain(v){v=v.replace(/<\/?(?:voice|pic|sticker|clip|toy|call)\b[^>]*>/gi,'').trim();if(v)out.push({kind:'text',text:v});}
 for(const m of text.matchAll(token)){plain(text.slice(last,m.index));const type=(m[1]||'call').toLowerCase(),payload=(m[2]??m[3]??'').replace(/<\/?(?:voice|pic|sticker|clip|toy|call)\b[^>]*>/gi,'').trim();if(type==='call')out.push({kind:'call',text:payload||'语音来电'});else if(type==='clip')out.push({kind:'notice',text:'预录语音尚未接入'});else if(type!=='toy'&&payload)out.push({kind:{voice:'voice',pic:'picture',sticker:'sticker'}[type],text:payload});last=m.index+m[0].length;}
 plain(text.slice(last));return out.length?out:hasControl?[]:[{kind:'notice',text:'这条消息没有可显示的内容'}];
}
function richMessages(messages){return messages.flatMap(m=>m.kind?[m]:m.role==='assistant'?richParts(m.text).map(p=>({...m,...p})):[{...m,kind:'text'}]);}
function historyText(message){
 const m=message,tag={voice:'voice',picture:'pic',sticker:'sticker'}[m.kind];
 if(tag)return '<'+tag+'>'+m.text+'</'+tag+'>';
 if(m.kind==='call')return '【'+(m.role==='user'?'拨出语音电话':'语音来电')+'：'+(m.callOutcome||'已显示')+'】';
 return m.text;
}
function mediaCapabilities(settings){const s={...MEDIA_DEFAULTS,...settings};return {voice:s.ttsProvider==='elevenlabs'?!!(s.elevenKey&&s.elevenVoice&&s.elevenModel):!!(s.minimaxKey&&s.minimaxVoice&&s.minimaxModel),image:s.imageProvider==='openai'?!!(s.openaiImageKey&&s.openaiImageModel):!!(s.naiKey&&s.naiModel),stickers:Array.isArray(s.stickers)?s.stickers.map(x=>x.name):[]};}
function mediaDirective(cap={},inCall=false){return '\n手机支持的媒体标签写在每条 messages 的文字里：'+(cap.voice?'语音用 <voice>要说的话</voice>；可用 <call> 请求语音来电，只有玩家接听后才进入通话。':'未配置语音，不发送 voice 或 call 标签。')+(cap.image?'图片用 <pic>英文场景提示词或 tags</pic>。':'未配置生图，不发送 pic 标签。')+(cap.stickers?.length?'表情包用 <sticker>名字</sticker>；只能从这些名字中选：'+cap.stickers.join('、')+'。':'表情包库为空，不发送 sticker 标签。')+'标签不是普通文字，不要使用代码块；不要输出 clip（预录音尚未接入）。'+(inCall?'\n现在是已接通的语音通话，玩家通过打字说话，你的每一条普通文字或 voice 消息会依次朗读。说可以直接念出的短句，不叠加来电标签。':'');}

/* Mode injection for the main model; the regex owns the phone frontend. */
(()=>{
  const P=window.parent;
  function phones(){return [...P.document.querySelectorAll('iframe')].flatMap(frame=>{
    try{const match=(frame.name||frame.id).match(/^TH-message--(\d+)--/);const api=frame.contentWindow?.__rifugioImessagePhoneV1;return match&&api?[{index:Number(match[1]),frame,api}]:[];}catch{return [];}
  }).sort((a,b)=>b.index-a.index);}
  const listeners=[];
  let uninject=null;
  function syncMode(){
    uninject?.();uninject=null;
    if(typeof injectPrompts!=='function'||typeof getVariables!=='function')return;
    const ctx=P.SillyTavern?.getContext?.();if(!ctx||ctx.groupId)return;
    const settings=getVariables({type:'chat'}).rf_imessage_v1||{};
    const chatKey=JSON.stringify([ctx.groupId??'',ctx.characters?.[ctx.characterId]?.avatar??ctx.characterId??'',ctx.getCurrentChatId?.()??ctx.chatId??'']);
    let media={};try{media=JSON.parse(P.localStorage.getItem(mediaSettingsKey(chatKey))||'{}');}catch{}
    const content='以下只约束正文末尾的 <phone> 私聊，不改变正文的叙事视角。'+modeDirective(settings.mode,ctx.name1||'用户角色')+'先写完正文，再用一个 <phone> 输出 2—4 条本轮短信，messages 中每条为 {"role":"assistant","text":"短信内容"}。不要编造尚未发生的手机互动。'+mediaDirective(mediaCapabilities(media));
    uninject=injectPrompts([{id:'rf-phone-mode-v1',position:'in_chat',depth:0,role:'system',content,should_scan:false}]).uninject;
  }
  syncMode();P.addEventListener('rf-imessage-config-changed',syncMode);P.addEventListener('rf-imessage-media-changed',syncMode);
  if(typeof eventOn==='function'&&typeof tavern_events!=='undefined')for(const event of [tavern_events.CHAT_CHANGED,tavern_events.GENERATION_AFTER_COMMANDS].filter(Boolean))listeners.push(eventOn(event,syncMode));
  if(typeof eventOn==='function'&&typeof getButtonEvent==='function'){
    listeners.push(eventOn(getButtonEvent('打开小手机设置'),()=>{const latest=phones()[0];if(latest){latest.frame.scrollIntoView({block:'center',behavior:'smooth'});latest.api.openControls();}else P.toastr?.info('请先让角色输出一个完整的 <phone> 块。');}));
    listeners.push(eventOn(getButtonEvent('停止手机联动'),()=>{P.__rfPhoneInteraction?.stop();for(const phone of phones())phone.api.stopSession();try{P.__rifugioTavernToyPanelV1?.frame?.contentWindow?.RifugioToyPanel?.stop(true);}catch{}}));
  }
  window.addEventListener('pagehide',()=>{uninject?.();P.removeEventListener('rf-imessage-config-changed',syncMode);P.removeEventListener('rf-imessage-media-changed',syncMode);for(const listener of listeners)listener?.stop?.();},{once:true});
})();
